import {prepareLandscape,renderLandscape,landscapeSkyMask} from './landscape-engine.js';
let context;
self.onmessage=({data:{id,input}})=>{try{let result;if(input.kind==='prepare'){context=prepareLandscape(input);result={analysis:context.analysis,baseSky:new Float32Array(context.skyBase)};}else if(input.kind==='sky'){if(!context)throw Error('Prepare landscape first.');context.sky=landscapeSkyMask(input.baseSky,context.width,context.height,input.strokes);result={ready:true};}else if(input.kind==='render'){if(!context)throw Error('Prepare landscape first.');result=renderLandscape(context,input.params);}else throw Error('Unknown landscape job.');const transfer=[];if(result.data)transfer.push(result.data.buffer);if(result.baseSky)transfer.push(result.baseSky.buffer);self.postMessage({id,result},transfer);}catch(e){self.postMessage({id,error:e.message});}};
